2430	static void launch_prefill_fp8(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
2431	                               at::Tensor& out, at::Tensor& lse, const at::Tensor& cu_q,
2432	                               const std::optional<at::Tensor>& cu_k, const std::optional<at::Tensor>& seqused_k,
2433	                               const std::optional<at::Tensor>& page_table,
2434	                               const std::optional<at::Tensor>& qd_, const std::optional<at::Tensor>& kd_,
2435	                               const std::optional<at::Tensor>& vd_,
2436	                               int b, int hq, int hkv, int hd, int hdv, int total_q, int max_seqlen_q,
2437	                               double scale, bool causal, double softcap, int win_l, int win_r, cudaStream_t stream) {
2438	    const bool paged = page_table.has_value();
2439	    int rep = hq / hkv;
2440	    long q_row = q.stride(0), q_head = q.stride(1);
