2444	    long o_row = out.stride(0), o_head = out.stride(1);
2445	    int block_size = paged ? (int)k.size(1) : 0;
2446	    int page_stride = paged ? (int)page_table->stride(0) : 0;
2447	    int tiles_m = (max_seqlen_q * rep + CTA_M - 1) / CTA_M;
2448	    const float* qd = qd_ ? (const float*)qd_->data_ptr() : nullptr;
