2465	// FAST PATH 2: decode (q_len small), flash-decoding with split-KV.
2466	//
2467	// Memory-bound regime (the QK/PV are tiny GEMVs; the bottleneck is streaming the paged KV cache).
2468	// One WARP per (batch, kv_head, kv_split) work-item; 128-thread blocks pack 4 independent warps.
2469	// A warp processes ALL packed-GQA rows (M = q_len * rep) of its (b,hk) over its key slice, with
2470	// lane L owning the contiguous head-dim chunk [L*per, L*per+per) so K/V loads are 256 B coalesced and
2471	// the QK dot is a single warp reduction. Each warp writes a NORMALIZED partial (O_s, lse_s) to scratch;
2472	// `combine_kernel` does the across-split flash reduction. Matches the scalar fallback semantics
2473	// (qk_scale = scale*qd*kd, softcap after scale, causal + sliding-window, q_abs = klen - sq + qpos).
2474	namespace dec {
2475	constexpr int WARP = 32, WARPS_PER_BLOCK = 4, DEC_THREADS = WARP * WARPS_PER_BLOCK;
2476	
2477	__device__ __forceinline__ float wreduce_sum(float v) {
2478	#pragma unroll
2479	    for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
2480	    return v;
2481	}
2482	
2483	// One warp = one (b, hk, split). MAXM bounds the packed-GQA rows; per/perv = HD/32, HDV/32 dims/lane.
2484	template <typename TIn, typename TOut, int HD, int HDV, int MAXM>
2485	__global__ void decode_kernel(
2486	        const TIn* __restrict__ Q, const TIn* __restrict__ K, const TIn* __restrict__ V,
2487	        float* __restrict__ Opart, float* __restrict__ LSEpart,
2488	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
2489	        const int* __restrict__ page_table,
2490	        const float* __restrict__ q_descale, const float* __restrict__ k_descale, const float* __restrict__ v_descale,
2491	        int ds_b, int ds_h,
2492	        long q_row, long q_head, long k_row, long k_head, long v_row, long v_head,
2493	        int batch, int hq, int hkv, int rep, int total_q, int block_size, int page_stride,
2494	        int num_splits, float scale, float softcap, int win_l, int win_r, int causal) {
2495	    constexpr int per = HD / 32, perv = HDV / 32;
2496	    const int witem = blockIdx.x * WARPS_PER_BLOCK + (threadIdx.x >> 5);
2497	    const int lane = threadIdx.x & 31;
2498	    if (witem >= num_splits * hkv * batch) return;
2499	    // work-item -> (b, hk, split)
2500	    const int split = witem % num_splits;
2501	    int tmp = witem / num_splits;
2502	    const int hk = tmp % hkv;
2503	    const int b = tmp / hkv;
2504	    // b is bounded by the launch (grid sized to batch); guard:
2505	    const int q0 = cu_q[b];
2506	    const int sq = cu_q[b + 1] - q0;
2507	    if (sq <= 0) return;
2508	    const int klen = seqused_k ? seqused_k[b] : (cu_k[b + 1] - cu_k[b]);
2509	    const int M = sq * rep;
2510	
2511	    const long ds_idx = (long)b * ds_b + (long)hk * ds_h;
2512	    const float qd = q_descale ? q_descale[ds_idx] : 1.f;
2513	    const float kd = k_descale ? k_descale[ds_idx] : 1.f;
2514	    const float vd = v_descale ? v_descale[ds_idx] : 1.f;
2515	    const float qk_scale = scale * qd * kd;
2516	
2517	    // split's key range
2518	    const int span = (klen + num_splits - 1) / num_splits;
2519	    const int jlo = split * span;
2520	    const int jhi = min(jlo + span, klen);
2521	
2522	    float qreg[MAXM][per];
2523	    float acc[MAXM][perv];
2524	    float mrow[MAXM], lrow[MAXM];
2525	    int qabs[MAXM];
2526	#pragma unroll
2527	    for (int mi = 0; mi < MAXM; ++mi) {
2528	        if (mi >= M) break;
2529	        const int qpos = mi / rep, r = mi % rep;
2530	        const int head = hk * rep + r;
2531	        const TIn* qp = Q + (long)(q0 + qpos) * q_row + (long)head * q_head;
2532	#pragma unroll
2533	        for (int e = 0; e < per; ++e) qreg[mi][e] = to_float<TIn>(qp[lane * per + e]);
2534	#pragma unroll
2535	        for (int e = 0; e < perv; ++e) acc[mi][e] = 0.f;
2536	        mrow[mi] = -INFINITY; lrow[mi] = 0.f;
2537	        qabs[mi] = klen - sq + qpos;
2538	    }
2539	
2540	    // Software-pipelined K/V load: issue key (j+1)'s gmem loads (including the dependent page_table
2541	    // lookup) while computing on key j, so the load latency overlaps the (short) softmax compute.
2542	    auto load_key = [&](int j, float* kx, float* vx) {
2543	        long krow;
2544	        if (page_table) { int blk = page_table[(long)b * page_stride + j / block_size]; krow = (long)blk * block_size + (j % block_size); }
2545	        else            { krow = (long)cu_k[b] + j; }
2546	        const TIn* kp = K + krow * k_row + (long)hk * k_head;
2547	        const TIn* vp = V + krow * v_row + (long)hk * v_head;
2548	#pragma unroll
2549	        for (int e = 0; e < per; ++e)  kx[e] = to_float<TIn>(kp[lane * per + e]);
2550	#pragma unroll
2551	        for (int e = 0; e < perv; ++e) vx[e] = to_float<TIn>(vp[lane * perv + e]);
2552	    };
2553	    float kxA[per], vxA[perv], kxB[per], vxB[perv];
2554	    if (jlo < jhi) load_key(jlo, kxA, vxA);
2555	    for (int j = jlo; j < jhi; ++j) {
2556	        const bool A = ((j - jlo) & 1) == 0;
2557	        float* kx = A ? kxA : kxB; float* vx = A ? vxA : vxB;
2558	        if (j + 1 < jhi) load_key(j + 1, A ? kxB : kxA, A ? vxB : vxA);   // prefetch next
2559	#pragma unroll
2560	        for (int mi = 0; mi < MAXM; ++mi) {
2561	            if (mi >= M) break;
2562	            const int qa = qabs[mi];
2563	            bool masked = (causal && j > qa) || (win_l >= 0 && j < qa - win_l) || (win_r >= 0 && j > qa + win_r);
2564	            float dot = 0.f;
2565	#pragma unroll
2566	            for (int e = 0; e < per; ++e) dot += qreg[mi][e] * kx[e];
2567	            float s = wreduce_sum(dot) * qk_scale;
2568	            if (softcap > 0.f) s = softcap * tanhf(s / softcap);
2569	            if (masked) continue;
2570	            float mnew = fmaxf(mrow[mi], s);
2571	            float corr = __expf(mrow[mi] - mnew), p = __expf(s - mnew);
2572	            lrow[mi] = lrow[mi] * corr + p;
2573	#pragma unroll
2574	            for (int e = 0; e < perv; ++e) acc[mi][e] = acc[mi][e] * corr + p * (vx[e] * vd);
2575	            mrow[mi] = mnew;
2576	        }
2577	    }
2578	
2579	#pragma unroll
2580	    for (int mi = 0; mi < MAXM; ++mi) {
2581	        if (mi >= M) break;
2582	        const int qpos = mi / rep, r = mi % rep;
2583	        const int head = hk * rep + r, qidx = q0 + qpos;
2584	        const float inv = lrow[mi] > 0.f ? 1.f / lrow[mi] : 0.f;
2585	        float* op = Opart + (((long)split * total_q + qidx) * hq + head) * HDV;
2586	#pragma unroll
2587	        for (int e = 0; e < perv; ++e) op[lane * perv + e] = acc[mi][e] * inv;
2588	        if (lane == 0)
2589	            LSEpart[((long)split * hq + head) * total_q + qidx] =
2590	                (lrow[mi] > 0.f) ? (mrow[mi] + __logf(lrow[mi])) : -INFINITY;
2591	    }
2592	}
